class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_close = {ticker: None for ticker in self.symbols}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_red_streak = 0

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

        self.SetWarmUp(250, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = data.Bars
        available = {
            ticker: bars.ContainsKey(symbol)
            for ticker, symbol in self.symbols.items()
        }

        old_closes = dict(self.previous_close)
        old_spy_sma_200 = self.previous_spy_sma_200
        old_spy_sma_50 = self.previous_spy_sma_50

        if available["SPY"]:
            spy_bar = bars[self.symbols["SPY"]]
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)

        if available["AAPL"]:
            aapl_bar = bars[self.symbols["AAPL"]]
            old_aapl_close = old_closes["AAPL"]
            if old_aapl_close is not None and aapl_bar.Close < old_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)

        for ticker, is_available in available.items():
            if is_available:
                self.previous_close[ticker] = bars[self.symbols[ticker]].Close

        if available["SPY"]:
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        if not all(available.values()) or self.IsWarmingUp:
            return

        if not (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and old_closes["SPY"] is not None
            and old_spy_sma_200 is not None
            and old_spy_sma_50 is not None
        ):
            return

        spy_close = bars[self.symbols["SPY"]].Close
        aapl_close = bars[self.symbols["AAPL"]].Close

        # Sells are evaluated before buys.
        if self.strategy_a_quantity > 0:
            crossed_below_sma_50 = (
                old_closes["SPY"] >= old_spy_sma_50
                and spy_close < self.spy_sma_50.Current.Value
            )
            if crossed_below_sma_50:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_quantity)
                self.strategy_a_quantity = 0

        if self.strategy_b_quantity > 0 and self.aapl_rsi_14.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_quantity)
            self.strategy_b_quantity = 0

        if self.strategy_a_quantity == 0:
            crossed_above_sma_200 = (
                old_closes["SPY"] <= old_spy_sma_200
                and spy_close > self.spy_sma_200.Current.Value
            )
            if crossed_above_sma_200:
                quantity = int(
                    (self.Portfolio.TotalPortfolioValue * Decimal("0.40"))
                    / spy_close
                )
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.strategy_a_quantity = quantity

        if self.strategy_b_quantity == 0 and self.aapl_red_streak >= 3:
            allocation = Decimal("20000")
            if self.Portfolio.Cash >= allocation:
                quantity = int(allocation / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_quantity = quantity

