class ParallelStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        # One additional observation is needed to compare a fully formed
        # 200-day SMA with its value on the preceding trading day.
        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data):
        bars = data.Bars
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        previous_spy_close = self.previous_closes.get(spy)
        previous_aapl_close = self.previous_closes.get(aapl)

        if bars.ContainsKey(spy):
            spy_close = bars[spy].Close
            self.spy_sma_200.Update(data.Time, spy_close)
            self.spy_sma_50.Update(data.Time, spy_close)
        else:
            spy_close = None

        if bars.ContainsKey(aapl):
            aapl_close = bars[aapl].Close
            self.aapl_rsi_14.Update(data.Time, aapl_close)
            if previous_aapl_close is not None:
                if aapl_close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
        else:
            aapl_close = None

        all_bars_present = all(
            bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
        )

        if all_bars_present and indicators_ready and not self.IsWarmingUp:
            # Sells are evaluated before buys.
            spy_crossed_below_sma_50 = (
                previous_spy_close >= self.previous_spy_sma_50
                and spy_close < self.spy_sma_50.Current.Value
            )
            if self.strategy_a_shares > 0 and spy_crossed_below_sma_50:
                self.MarketOrder(spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

            if (
                self.strategy_b_shares > 0
                and self.aapl_rsi_14.Current.Value > 60
            ):
                self.MarketOrder(aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

            spy_crossed_above_sma_200 = (
                previous_spy_close <= self.previous_spy_sma_200
                and spy_close > self.spy_sma_200.Current.Value
            )
            if self.strategy_a_shares == 0 and spy_crossed_above_sma_200:
                shares = floor(
                    0.40 * float(self.Portfolio.TotalPortfolioValue)
                    / float(spy_close)
                )
                if shares > 0:
                    self.MarketOrder(spy, shares)
                    self.strategy_a_shares = shares

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                allocation = 20_000
                if self.Portfolio.Cash >= allocation:
                    shares = floor(allocation / float(aapl_close))
                    if shares > 0:
                        self.MarketOrder(aapl, shares)
                        self.strategy_b_shares = shares

        if bars.ContainsKey(spy):
            self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        for symbol in self.symbols.values():
            if bars.ContainsKey(symbol):
                self.previous_closes[symbol] = bars[symbol].Close

