            14, MovingAverageType.Wilders
        )

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy = bars.get("SPY")
        aapl = bars.get("AAPL")

        old_spy_close = self.previous_spy_close
        old_spy_sma_200 = self.previous_spy_sma_200
        old_spy_sma_50 = self.previous_spy_sma_50

        if spy is not None:
            self.spy_sma_200.Update(spy.EndTime, spy.Close)
            self.spy_sma_50.Update(spy.EndTime, spy.Close)
            self.previous_spy_close = spy.Close
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        if aapl is not None:
            old_aapl_close = self.previous_aapl_close
            self.aapl_rsi_14.Update(aapl.EndTime, aapl.Close)
            if old_aapl_close is not None:
                if aapl.Close < old_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl.Close

        if len(bars) != len(self.symbols):
            return

        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and old_spy_close is not None
            and old_spy_sma_200 is not None
            and old_spy_sma_50 is not None
            and self.previous_aapl_close is not None
        )
        if not indicators_ready:
            return

        spy_close = spy.Close
        current_sma_200 = self.spy_sma_200.Current.Value
        current_sma_50 = self.spy_sma_50.Current.Value

        if self.strategy_a_shares > 0:
            crossed_below_sma_50 = (
                old_spy_close >= old_spy_sma_50
                and spy_close < current_sma_50
            )
            if crossed_below_sma_50:
                self.MarketOrder(
                    self.symbols["SPY"], -self.strategy_a_shares
                )
                self.strategy_a_shares = 0
        else:
            crossed_above_sma_200 = (
                old_spy_close <= old_spy_sma_200
                and spy_close > current_sma_200
            )
            if crossed_above_sma_200:
                quantity = int(
                    (self.Portfolio.TotalPortfolioValue * 0.40) / spy_close
                )
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares > 0:
            if self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(
                    self.symbols["AAPL"], -self.strategy_b_shares
                )
                self.strategy_b_shares = 0
        elif self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = int(20_000 // aapl.Close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.strategy_b_shares = quantity

