class MovingAverageAndStreakAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = self.SMA(self.symbols["SPY"], 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(self.symbols["SPY"], 50, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.pending_orders = {}

        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_close = data.Bars[spy].Close
            spy_sma_200 = self.spy_sma_200.Current.Value
            spy_sma_50 = self.spy_sma_50.Current.Value
        else:
            spy_close = None
            spy_sma_200 = None
            spy_sma_50 = None

        if data.Bars.ContainsKey(aapl):
            aapl_close = data.Bars[aapl].Close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close
        else:
            aapl_close = None

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )
        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
        )

        if (
            all_bars_present
            and indicators_ready
            and not self.IsWarmingUp
            and self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
        ):
            self._evaluate_strategy_a(spy_close, spy_sma_200, spy_sma_50)
            self._evaluate_strategy_b(aapl_close)

        if spy_close is not None:
            self.previous_spy_close = spy_close
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = spy_sma_200
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = spy_sma_50

    def _evaluate_strategy_a(self, close, sma_200, sma_50):
        if "A" in self.pending_orders.values():
            return

        if self.strategy_a_shares > 0:
            sma_50_crossed = (
                self.previous_spy_sma_50 <= self.previous_spy_close
                and sma_50 > close
            ) or (
                self.previous_spy_sma_50 >= self.previous_spy_close
                and sma_50 < close
            )
            if sma_50_crossed:
                self._submit_lot_order("A", -self.strategy_a_shares)
            return

        crossed_above_200 = (
            self.previous_spy_close <= self.previous_spy_sma_200
            and close > sma_200
        )
        if crossed_above_200:
            quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // close)
            if quantity > 0:
                self._submit_lot_order("A", quantity)

    def _evaluate_strategy_b(self, close):
        if "B" in self.pending_orders.values():
            return

        if self.strategy_b_shares > 0:
            if self.aapl_rsi_14.Current.Value > 60:
                self._submit_lot_order("B", -self.strategy_b_shares)
            return

        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            quantity = int(20_000 // close)
            if quantity > 0:
                self._submit_lot_order("B", quantity)

    def _submit_lot_order(self, strategy, quantity):
        symbol = self.symbols["SPY"] if strategy == "A" else self.symbols["AAPL"]
        ticket = self.MarketOrder(symbol, quantity)
        self.pending_orders[ticket.OrderId] = strategy

    def OnOrderEvent(self, order_event):
        if order_event.OrderId not in self.pending_orders:
            return

        strategy = self.pending_orders[order_event.OrderId]
        if order_event.FillQuantity != 0:
            if strategy == "A":
                self.strategy_a_shares += order_event.FillQuantity
            else:
                self.strategy_b_shares += order_event.FillQuantity

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            del self.pending_orders[order_event.OrderId]

