    def on_data(self, data):
        spy_bar = data.bars.get(self.symbols["SPY"])
        aapl_bar = data.bars.get(self.symbols["AAPL"])

        current_spy_sma_200 = None
        current_spy_sma_50 = None
        if spy_bar is not None:
            spy_close = float(spy_bar.close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 200:
                current_spy_sma_200 = sum(self.spy_closes) / 200.0
                current_spy_sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        all_bars_present = all(
            data.bars.get(symbol) is not None for symbol in self.symbols.values()
        )

        indicators_ready = (
            current_spy_sma_200 is not None
            and self.spy_previous_sma_200 is not None
            and self.spy_previous_sma_50 is not None
            and self.spy_previous_close is not None
            and self.aapl_previous_close is not None
            and self.aapl_rsi.is_ready
        )

        if all_bars_present and indicators_ready:
            spy_close = float(spy_bar.close)
            aapl_close = float(aapl_bar.close)

            # Sells are evaluated before buys.
            spy_crossed_below_sma_50 = (
                self.spy_previous_close >= self.spy_previous_sma_50
                and spy_close < current_spy_sma_50
            )
            if self.strategy_a_shares > 0 and spy_crossed_below_sma_50:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
