            if self.strategy_b_shares > 0 and self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0

            spy_crossed_above_sma_200 = (
                self.spy_previous_close <= self.spy_previous_sma_200
                and spy_close > current_spy_sma_200
            )
            if self.strategy_a_shares == 0 and spy_crossed_above_sma_200:
                shares = floor(
                    0.40 * float(self.portfolio.total_portfolio_value) / spy_close
                )
                if shares > 0:
                    self.market_order(self.symbols["SPY"], shares)
                    self.strategy_a_shares = shares

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
