class ParallelSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_closes = []
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to consume every available bar, even
        # on a date on which one of the other subscriptions has no bar.
        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.close))
            if len(self.spy_closes) > 201:
                self.spy_closes.pop(0)

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_close)

        # Every strategy is skipped unless all five subscriptions supplied a
        # bar for this date.
        if len(bars) != len(self.tickers):
            return

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and self._spy_crosses_below_sma(50):
            self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi.is_ready
            and float(self.aapl_rsi.current.value) > 60
        ):
            self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self._spy_crosses_above_sma(200):
            spy_close = float(bars["SPY"].close)
            shares = int((0.40 * float(self.portfolio.total_portfolio_value)) // spy_close)
            if shares > 0:
                self.market_order(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_rsi.is_ready:
            if self.aapl_red_streak >= 3 and float(self.portfolio.cash) >= 20_000:
                aapl_close = float(bars["AAPL"].close)
                shares = int(20_000 // aapl_close)
                if shares > 0:
                    self.market_order(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

    def _spy_crosses_above_sma(self, period):
        if len(self.spy_closes) < period + 1:
            return False
        previous_close = self.spy_closes[-2]
        current_close = self.spy_closes[-1]
        previous_sma = sum(self.spy_closes[-period - 1:-1]) / period
        current_sma = sum(self.spy_closes[-period:]) / period
        return previous_close <= previous_sma and current_close > current_sma

    def _spy_crosses_below_sma(self, period):
        if len(self.spy_closes) < period + 1:
            return False
        previous_close = self.spy_closes[-2]
        current_close = self.spy_closes[-1]
        previous_sma = sum(self.spy_closes[-period - 1:-1]) / period
        current_sma = sum(self.spy_closes[-period:]) / period
        return previous_close >= previous_sma and current_close < current_sma

