        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_previous_close = None
        self.spy_previous_sma_200 = None
        self.spy_previous_sma_50 = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            spy_bar = data.Bars[spy]
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)
        else:
            spy_bar = None

        if data.Bars.ContainsKey(aapl):
            aapl_bar = data.Bars[aapl]
            if self.aapl_previous_close is not None:
                if aapl_bar.Close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)
        else:
            aapl_bar = None

        all_bars_present = all(
            data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()
        )

        if all_bars_present:
            self._evaluate_spy_strategy(spy_bar)
            self._evaluate_aapl_strategy(aapl_bar)

        if spy_bar is not None:
            self.spy_previous_close = spy_bar.Close
            if self.spy_sma_200.IsReady:
                self.spy_previous_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.spy_previous_sma_50 = self.spy_sma_50.Current.Value

        if aapl_bar is not None:
            self.aapl_previous_close = aapl_bar.Close

    def _evaluate_spy_strategy(self, bar):
        indicators_ready = self.spy_sma_200.IsReady and self.spy_sma_50.IsReady
        previous_values_ready = (
            self.spy_previous_close is not None
            and self.spy_previous_sma_200 is not None
            and self.spy_previous_sma_50 is not None
        )
        if not indicators_ready or not previous_values_ready:
            return

        close = bar.Close
        if self.spy_lot > 0:
            crossed_below_sma_50 = (
                self.spy_previous_close >= self.spy_previous_sma_50
                and close < self.spy_sma_50.Current.Value
            )
            if crossed_below_sma_50:
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        else:
            crossed_above_sma_200 = (
                self.spy_previous_close <= self.spy_previous_sma_200
                and close > self.spy_sma_200.Current.Value
            )
            if crossed_above_sma_200:
                shares = int((self.Portfolio.TotalPortfolioValue * 0.40) / close)
                if shares > 0:
                    self.MarketOrder(self.symbols["SPY"], shares)
                    self.spy_lot = shares

    def _evaluate_aapl_strategy(self, bar):
        if not self.aapl_rsi_14.IsReady or self.aapl_previous_close is None:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            shares = int(20_000 / bar.Close)
            if shares > 0:
                self.MarketOrder(self.symbols["AAPL"], shares)
                self.aapl_lot = shares

