        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) < 201 or len(self.aapl_closes) < 4 or not self.aapl_rsi.is_ready:
            self._update_spy_cross_state()
            return

        sma_200 = sum(list(self.spy_closes)[-200:]) / 200.0
        sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and self._crosses_below(
            self.previous_spy_close, self.previous_sma_50, spy_close, sma_50
        ):
            self.market_order("SPY", -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and float(self.aapl_rsi.current.value) > 60:
            self.market_order("AAPL", -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and self._crosses_above(
            self.previous_spy_close, self.previous_sma_200, spy_close, sma_200
        ):
            quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / spy_close)
            if quantity > 0:
                self.market_order("SPY", quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self._aapl_red_streak_at_least_three():
            available_cash = float(self.portfolio.cash)
            if available_cash >= 20_000:
                quantity = floor(20_000 / aapl_close)
                if quantity > 0:
                    self.market_order("AAPL", quantity)
                    self.aapl_lot = quantity

        self.previous_spy_close = spy_close
        self.previous_sma_200 = sma_200
        self.previous_sma_50 = sma_50

    def _update_spy_cross_state(self):
        if not self.spy_closes:
            return
        self.previous_spy_close = self.spy_closes[-1]
        if len(self.spy_closes) >= 200:
            self.previous_sma_200 = sum(list(self.spy_closes)[-200:]) / 200.0
        if len(self.spy_closes) >= 50:
            self.previous_sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0

    def _aapl_red_streak_at_least_three(self):
        closes = list(self.aapl_closes)
        return closes[-1] < closes[-2] < closes[-3] < closes[-4]

    @staticmethod
    def _crosses_above(previous_x, previous_y, current_x, current_y):
        return (
            previous_x is not None
            and previous_y is not None
            and previous_x <= previous_y
            and current_x > current_y
        )

    @staticmethod
    def _crosses_below(previous_x, previous_y, current_x, current_y):
        return (
            previous_x is not None
            and previous_y is not None
            and previous_x >= previous_y
            and current_x < current_y
        )

