class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=200)
        self.aapl_closes = deque(maxlen=4)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_spy_above_sma200 = None
        self.previous_spy_above_sma50 = None
        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        self._apply_splits(data)

        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state history is maintained even on a day when another symbol is absent.
        spy = bars.get("SPY")
        if spy is not None:
            self._update_spy_state(Decimal(spy.Close))

        aapl = bars.get("AAPL")
        if aapl is not None:
            self.aapl_closes.append(Decimal(aapl.Close))

        if len(bars) != len(self.symbols):
            return

        # Every indicator and rolling history used by the system must be fully formed.
        if len(self.spy_closes) < 200 or len(self.aapl_closes) < 4 or not self.aapl_rsi.IsReady:
            return

        spy_close = Decimal(spy.Close)
        sma200 = sum(self.spy_closes) / Decimal(200)
        sma50 = sum(list(self.spy_closes)[-50:]) / Decimal(50)
        spy_above_200 = spy_close > sma200
        spy_above_50 = spy_close > sma50

        # Sells are evaluated before buys.
        if (
            self.spy_lot > 0
            and self.previous_spy_above_sma50 is True
            and not spy_above_50
        ):
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.Current.Value > Decimal(60):
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if (
            self.spy_lot == 0
            and self.previous_spy_above_sma200 is False
            and spy_above_200
        ):
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        aapl_close = Decimal(aapl.Close)
        red_three_days = all(
            self.aapl_closes[index] < self.aapl_closes[index - 1]
            for index in range(1, 4)
        )
        if self.aapl_lot == 0 and red_three_days and self.Portfolio.Cash >= Decimal(20_000):
            quantity = floor(Decimal(20_000) / aapl_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.aapl_lot = quantity

        self.previous_spy_above_sma200 = spy_above_200
        self.previous_spy_above_sma50 = spy_above_50

    def _update_spy_state(self, close):
        if len(self.spy_closes) == 200:
            sma200 = sum(self.spy_closes) / Decimal(200)
            sma50 = sum(list(self.spy_closes)[-50:]) / Decimal(50)
            self.previous_spy_above_sma200 = self.spy_closes[-1] > sma200
            self.previous_spy_above_sma50 = self.spy_closes[-1] > sma50
        self.spy_closes.append(close)

    def _apply_splits(self, data):
        for symbol, attribute in ((self.symbols["SPY"], "spy_lot"),
                                  (self.symbols["AAPL"], "aapl_lot")):
            if data.Splits.ContainsKey(symbol):
                split = data.Splits[symbol]
                if split.Type == SplitType.SplitOccurred and split.SplitFactor != 0:
                    shares = getattr(self, attribute)
                    setattr(self, attribute, int(Decimal(shares) / Decimal(split.SplitFactor)))

