class ParallelDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=200)
        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        complete_slice = True
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                complete_slice = False
                continue
            bars[ticker] = data.Bars[symbol]

        spy_today_sma_200 = None
        spy_today_sma_50 = None
        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 200:
                spy_today_sma_200 = sum(self.spy_closes) / 200.0
                spy_today_sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        if complete_slice:
            self._evaluate_sells(bars, spy_today_sma_50)
            self._evaluate_buys(bars, spy_today_sma_200)

        if "SPY" in bars:
            self.previous_spy_close = float(bars["SPY"].Close)
            if spy_today_sma_200 is not None:
                self.previous_spy_sma_200 = spy_today_sma_200
                self.previous_spy_sma_50 = spy_today_sma_50
        if "AAPL" in bars:
            self.previous_aapl_close = float(bars["AAPL"].Close)

    def _evaluate_sells(self, bars, spy_today_sma_50):
        spy_close = float(bars["SPY"].Close)
        spy_crossed_below_sma_50 = (
            self.previous_spy_close is not None
            and self.previous_spy_sma_50 is not None
            and spy_today_sma_50 is not None
            and self.previous_spy_close >= self.previous_spy_sma_50
            and spy_close < spy_today_sma_50
        )
        if self.strategy_a_shares > 0 and spy_crossed_below_sma_50:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi.IsReady
            and float(self.aapl_rsi.Current.Value) > 60.0
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

    def _evaluate_buys(self, bars, spy_today_sma_200):
        spy_close = float(bars["SPY"].Close)
        spy_crossed_above_sma_200 = (
            self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and spy_today_sma_200 is not None
            and self.previous_spy_close <= self.previous_spy_sma_200
            and spy_close > spy_today_sma_200
        )
        if self.strategy_a_shares == 0 and spy_crossed_above_sma_200:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = floor(target_value / spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000.0
            if float(self.Portfolio.Cash) >= cash_to_invest:
                aapl_close = float(bars["AAPL"].Close)
                quantity = floor(cash_to_invest / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.strategy_b_shares = quantity

