        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                self._update_available_history(data)
                return
            bars[ticker] = data.Bars[symbol]

        spy_bar = bars["SPY"]
        aapl_bar = bars["AAPL"]

        prior_spy_close = self.previous_spy_close
        prior_spy_sma_200 = self.previous_spy_sma_200
        prior_spy_sma_50 = self.previous_spy_sma_50

        self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
        self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)
        self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)

        if self.previous_aapl_close is not None:
            if aapl_bar.Close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and prior_spy_close is not None
            and prior_spy_sma_200 is not None
            and prior_spy_sma_50 is not None
        )

        if indicators_ready:
            # Sells are evaluated before buys.
            if self.strategy_a_quantity > 0:
                crossed_below_sma_50 = (
                    prior_spy_close >= prior_spy_sma_50
                    and spy_bar.Close < self.spy_sma_50.Current.Value
                )
                if crossed_below_sma_50:
                    self.MarketOrder(self.symbols["SPY"], -self.strategy_a_quantity)
                    self.strategy_a_quantity = 0

            if self.strategy_b_quantity > 0 and self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_quantity)
                self.strategy_b_quantity = 0

            if self.strategy_a_quantity == 0:
                crossed_above_sma_200 = (
                    prior_spy_close <= prior_spy_sma_200
                    and spy_bar.Close > self.spy_sma_200.Current.Value
                )
                if crossed_above_sma_200:
                    quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(self.symbols["SPY"], quantity)
                        self.strategy_a_quantity = quantity

            if self.strategy_b_quantity == 0 and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20_000:
                    quantity = int(20_000 // aapl_bar.Close)
                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity)
                        self.strategy_b_quantity = quantity

        self.previous_spy_close = spy_bar.Close
        self.previous_spy_sma_200 = (
            self.spy_sma_200.Current.Value if self.spy_sma_200.IsReady else None
        )
        self.previous_spy_sma_50 = (
            self.spy_sma_50.Current.Value if self.spy_sma_50.IsReady else None
        )
        self.previous_aapl_close = aapl_bar.Close

    def _update_available_history(self, data):
        spy = self.symbols["SPY"]
        if data.Bars.ContainsKey(spy):
            bar = data.Bars[spy]
            self.spy_sma_200.Update(bar.EndTime, bar.Close)
            self.spy_sma_50.Update(bar.EndTime, bar.Close)
            self.previous_spy_close = bar.Close
            self.previous_spy_sma_200 = (
                self.spy_sma_200.Current.Value if self.spy_sma_200.IsReady else None
            )
            self.previous_spy_sma_50 = (
                self.spy_sma_50.Current.Value if self.spy_sma_50.IsReady else None
            )

        aapl = self.symbols["AAPL"]
        if data.Bars.ContainsKey(aapl):
            bar = data.Bars[aapl]
            self.aapl_rsi_14.Update(bar.EndTime, bar.Close)
            if self.previous_aapl_close is not None:
                if bar.Close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = bar.Close

