class ParallelSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=201)
        self.aapl_closes = deque(maxlen=15)
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities continue to update even on an incomplete slice.
        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            if self.aapl_closes:
                if aapl_close < self.aapl_closes[-1]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_closes.append(aapl_close)
            self.aapl_rsi.Update(data.Time, aapl_close)

        # Every subscribed ticker must have today's bar before any rule is checked.
        if len(bars) != len(self.symbols):
            return

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        # Sells are evaluated before buys. Each order is limited to its strategy's lot.
        if self.spy_lot > 0 and self._spy_crossed_below_sma(50):
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and self._spy_crossed_above_sma(200):
            quantity = floor(0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            allocation = 20_000
            if float(self.Portfolio.Cash) >= allocation:
                quantity = floor(allocation / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _spy_crossed_above_sma(self, period):
        if len(self.spy_closes) < period + 1:
            return False
        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[-period - 1:-1]) / period
        today_sma = sum(closes[-period:]) / period
        return closes[-2] <= yesterday_sma and closes[-1] > today_sma

    def _spy_crossed_below_sma(self, period):
        if len(self.spy_closes) < period + 1:
            return False
        closes = list(self.spy_closes)
        yesterday_sma = sum(closes[-period - 1:-1]) / period
        today_sma = sum(closes[-period:]) / period
        return closes[-2] >= yesterday_sma and closes[-1] < today_sma

