        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.rsi_previous_close = None
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_average_gain = None
        self.rsi_average_loss = None
        self.aapl_rsi = None

        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.spy_sma_200 = None
        self.spy_sma_50 = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        if "SPY" in bars:
            self._update_spy(bars["SPY"].Close)
        if "AAPL" in bars:
            self._update_aapl(bars["AAPL"].Close)

        all_bars_present = len(bars) == len(self.symbols)
        if all_bars_present:
            self._evaluate_sells()
            self._evaluate_buys(bars)

        if "SPY" in bars:
            self.previous_spy_close = Decimal(bars["SPY"].Close)
            self.previous_spy_sma_200 = self.spy_sma_200
            self.previous_spy_sma_50 = self.spy_sma_50

    def _update_spy(self, close):
        close = Decimal(close)
        self.spy_closes.append(close)
        self.spy_sma_200 = None
        self.spy_sma_50 = None

        if len(self.spy_closes) == 200:
            self.spy_sma_200 = sum(self.spy_closes) / Decimal(200)
            self.spy_sma_50 = sum(list(self.spy_closes)[-50:]) / Decimal(50)

    def _update_aapl(self, close):
        close = Decimal(close)
        if self.aapl_previous_close is not None:
            if close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            change = close - self.rsi_previous_close
            gain = max(change, Decimal(0))
            loss = max(-change, Decimal(0))

            if self.rsi_average_gain is None:
                self.rsi_seed_gains.append(gain)
                self.rsi_seed_losses.append(loss)
                if len(self.rsi_seed_gains) == 14:
                    self.rsi_average_gain = sum(self.rsi_seed_gains) / Decimal(14)
                    self.rsi_average_loss = sum(self.rsi_seed_losses) / Decimal(14)
            else:
                self.rsi_average_gain = (
                    self.rsi_average_gain * Decimal(13) + gain
                ) / Decimal(14)
                self.rsi_average_loss = (
                    self.rsi_average_loss * Decimal(13) + loss
                ) / Decimal(14)

            if self.rsi_average_gain is not None:
                if self.rsi_average_loss == 0:
                    self.aapl_rsi = Decimal(100)
                else:
                    relative_strength = (
                        self.rsi_average_gain / self.rsi_average_loss
                    )
                    self.aapl_rsi = Decimal(100) - (
                        Decimal(100) / (Decimal(1) + relative_strength)
                    )

        self.aapl_previous_close = close
        self.rsi_previous_close = close

    def _evaluate_sells(self):
        if self.strategy_a_shares > 0 and self._spy_crossed_below_sma_50():
            self.MarketOrder(
                self.symbols["SPY"], -self.strategy_a_shares, tag="Strategy A sell"
            )
            self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi is not None
            and self.aapl_rsi > Decimal(60)
        ):
            self.MarketOrder(
                self.symbols["AAPL"],
                -self.strategy_b_shares,
                tag="Strategy B sell",
            )
            self.strategy_b_shares = 0

    def _evaluate_buys(self, bars):
        if self.strategy_a_shares == 0 and self._spy_crossed_above_sma_200():
            close = Decimal(bars["SPY"].Close)
            target_value = Decimal(self.Portfolio.TotalPortfolioValue) * Decimal("0.40")
            quantity = floor(target_value / close)
            if quantity > 0:
                self.MarketOrder(
                    self.symbols["SPY"], quantity, tag="Strategy A buy"
                )
                self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash = Decimal(self.Portfolio.Cash)
            if cash >= Decimal(20_000):
                close = Decimal(bars["AAPL"].Close)
                quantity = floor(Decimal(20_000) / close)
                if quantity > 0:
                    self.MarketOrder(
                        self.symbols["AAPL"], quantity, tag="Strategy B buy"
                    )
                    self.strategy_b_shares = quantity

    def _spy_crossed_above_sma_200(self):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.spy_sma_200 is not None
            and self.previous_spy_close <= self.previous_spy_sma_200
            and self.spy_closes[-1] > self.spy_sma_200
        )

    def _spy_crossed_below_sma_50(self):
        return (
            self.previous_spy_close is not None
            and self.previous_spy_sma_50 is not None
            and self.spy_sma_50 is not None
            and self.previous_spy_close >= self.previous_spy_sma_50
            and self.spy_closes[-1] < self.spy_sma_50
        )

