                    if shares > 0:
                        self.market_order(self.symbols["AAPL"], shares)
                        self.strategy_b_shares = shares

        if "SPY" in bars and current_spy_sma_200 is not None:
            self.spy_previous_close = float(bars["SPY"].close)
            self.spy_previous_sma_200 = current_spy_sma_200
