class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.closes = {
            ticker: deque(maxlen=201) for ticker in self.symbols
        }
        self.aapl_red_streak = 0
        self.aapl_average_gain = None
        self.aapl_average_loss = None
        self.aapl_seed_gains = deque(maxlen=14)
        self.aapl_seed_losses = deque(maxlen=14)
        self.aapl_rsi = None

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        complete_day = True
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                complete_day = False
                continue
            bars[ticker] = data.Bars[symbol]

        previous_aapl_close = (
            self.closes["AAPL"][-1] if self.closes["AAPL"] else None
        )
        for ticker, bar in bars.items():
            self.closes[ticker].append(float(bar.Close))

        if "AAPL" in bars and previous_aapl_close is not None:
            aapl_close = float(bars["AAPL"].Close)
            if aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self._update_aapl_rsi(aapl_close - previous_aapl_close)

        if not complete_day:
            return

        spy_ready = len(self.closes["SPY"]) == 201
        aapl_rsi_ready = self.aapl_rsi is not None

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and spy_ready and self._spy_crosses_below_sma(50):
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and aapl_rsi_ready and self.aapl_rsi > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_ready and self._spy_crosses_above_sma(200):
            close = float(bars["SPY"].Close)
            quantity = floor((self.Portfolio.TotalPortfolioValue * 0.40) / close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if (
            self.aapl_lot == 0
            and aapl_rsi_ready
            and self.aapl_red_streak >= 3
        ):
            cash_to_invest = 20_000
            if self.Portfolio.Cash >= cash_to_invest:
                close = float(bars["AAPL"].Close)
                quantity = floor(cash_to_invest / close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _spy_crosses_above_sma(self, period):
        values = self.closes["SPY"]
        yesterday_close = values[-2]
        today_close = values[-1]
        yesterday_sma = sum(list(values)[-(period + 1):-1]) / period
        today_sma = sum(list(values)[-period:]) / period
        return yesterday_close <= yesterday_sma and today_close > today_sma

    def _spy_crosses_below_sma(self, period):
        values = self.closes["SPY"]
        yesterday_close = values[-2]
        today_close = values[-1]
        yesterday_sma = sum(list(values)[-(period + 1):-1]) / period
        today_sma = sum(list(values)[-period:]) / period
        return yesterday_close >= yesterday_sma and today_close < today_sma

    def _update_aapl_rsi(self, change):
        gain = max(change, 0.0)
        loss = max(-change, 0.0)
        if self.aapl_average_gain is None:
            self.aapl_seed_gains.append(gain)
            self.aapl_seed_losses.append(loss)
            if len(self.aapl_seed_gains) < 14:
                return
            self.aapl_average_gain = sum(self.aapl_seed_gains) / 14
            self.aapl_average_loss = sum(self.aapl_seed_losses) / 14
        else:
            self.aapl_average_gain = (self.aapl_average_gain * 13 + gain) / 14
            self.aapl_average_loss = (self.aapl_average_loss * 13 + loss) / 14

        if self.aapl_average_loss == 0:
            self.aapl_rsi = 100.0 if self.aapl_average_gain > 0 else 50.0
        else:
            relative_strength = self.aapl_average_gain / self.aapl_average_loss
            self.aapl_rsi = 100.0 - 100.0 / (1.0 + relative_strength)

