class DailyStrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=201)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            self.spy_closes.append(Decimal(spy_bar.Close))

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            close = Decimal(aapl_bar.Close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = close
            self.aapl_rsi.Update(aapl_bar.EndTime, close)

        if len(bars) != len(self.symbols):
            return

        spy_close = Decimal(spy_bar.Close)
        aapl_close = Decimal(aapl_bar.Close)

        spy_crosses_sma_200 = False
        spy_sma_50_cross = False
        if len(self.spy_closes) == 201:
            closes = list(self.spy_closes)
            previous_close = closes[-2]
            previous_sma_200 = sum(closes[:-1]) / Decimal(200)
            current_sma_200 = sum(closes[1:]) / Decimal(200)
            spy_crosses_sma_200 = (
                previous_close <= previous_sma_200
                and spy_close > current_sma_200
            )

            previous_sma_50 = sum(closes[-51:-1]) / Decimal(50)
            current_sma_50 = sum(closes[-50:]) / Decimal(50)
            spy_sma_50_cross = (
                previous_sma_50 <= previous_close
                and current_sma_50 > spy_close
            ) or (
                previous_sma_50 >= previous_close
                and current_sma_50 < spy_close
            )

        # All sells are evaluated before either strategy's buy.
        if self.strategy_a_shares > 0 and spy_sma_50_cross:
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > Decimal(60)
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crosses_sma_200:
            shares = int(
                (Decimal("0.40") * Decimal(self.Portfolio.TotalPortfolioValue))
                // spy_close
            )
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

        if (
            self.strategy_b_shares == 0
            and self.aapl_rsi.IsReady
            and self.aapl_red_streak >= 3
        ):
            cash = Decimal(self.Portfolio.CashBook["USD"].Amount)
            if cash >= Decimal(20000):
                shares = int(Decimal(20000) // aapl_close)
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

