            self.previous_spy_close = spy_close

    def _update_rsi(self, gain, loss):
        changes_seen = len(self.closes["AAPL"]) - 1
        if changes_seen == 14:
            values = list(self.closes["AAPL"])
            gains = []
            losses = []
            for index in range(1, len(values)):
                change = values[index] - values[index - 1]
                gains.append(max(change, 0.0))
                losses.append(max(-change, 0.0))
            self.rsi_average_gain = sum(gains) / 14.0
            self.rsi_average_loss = sum(losses) / 14.0
        elif changes_seen > 14 and self.rsi_average_gain is not None:
            self.rsi_average_gain = (self.rsi_average_gain * 13.0 + gain) / 14.0
            self.rsi_average_loss = (self.rsi_average_loss * 13.0 + loss) / 14.0

    def _rsi_value(self):
        if self.rsi_average_loss == 0.0:
            return 100.0 if self.rsi_average_gain > 0.0 else 50.0
        relative_strength = self.rsi_average_gain / self.rsi_average_loss
        return 100.0 - 100.0 / (1.0 + relative_strength)

