        self.aapl_rsi_14 = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_close = {}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_red_streak = 0

        # Each strategy owns and manages only its own lot.
        self.spy_lot = 0
        self.aapl_lot = 0

        self.SetWarmUp(200, Resolution.Daily)

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            prior_aapl_close = self.previous_close.get("AAPL")
            if prior_aapl_close is not None and aapl_bar.Close < prior_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = len(bars) == len(self.tickers)
        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
        )

        if all_bars_present and indicators_ready and not self.IsWarmingUp:
            spy_close = bars["SPY"].Close
            previous_spy_close = self.previous_close.get("SPY")

            # Sells are evaluated before buys.
            if (
                self.spy_lot > 0
                and previous_spy_close is not None
                and self.previous_spy_sma_50 is not None
                and previous_spy_close >= self.previous_spy_sma_50
                and spy_close < self.spy_sma_50.Current.Value
            ):
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0

            if self.aapl_lot > 0 and self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0

            if (
                self.spy_lot == 0
                and previous_spy_close is not None
                and self.previous_spy_sma_200 is not None
                and previous_spy_close <= self.previous_spy_sma_200
                and spy_close > self.spy_sma_200.Current.Value
            ):
                quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)
                    self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                cash_required = 20000
                if self.Portfolio.Cash >= cash_required:
                    quantity = int(floor(cash_required / bars["AAPL"].Close))
                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity)
                        self.aapl_lot = quantity

        # Market-state history advances continuously, even on a skipped rule day.
        for ticker, bar in bars.items():
            self.previous_close[ticker] = bar.Close
        if "SPY" in bars:
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

