            if self.previous_aapl_close is not None:
                change = aapl_close - self.previous_aapl_close
                self.aapl_red_streak = (
                    self.aapl_red_streak + 1 if change < 0 else 0
                )
                gain = max(change, 0.0)
                loss = max(-change, 0.0)

                if self.rsi_change_count < 14:
                    self.rsi_gain_sum += gain
                    self.rsi_loss_sum += loss
                    self.rsi_change_count += 1
                    if self.rsi_change_count == 14:
