class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_red_streak = 0

        # Each strategy owns a private lot.  The strategies use different
        # securities, so these quantities also identify their portfolio lots.
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = data.Bars
        available = {
            ticker: bars.ContainsKey(symbol)
            for ticker, symbol in self.symbols.items()
        }

        spy_bar = bars[self.symbols["SPY"]] if available["SPY"] else None
        aapl_bar = bars[self.symbols["AAPL"]] if available["AAPL"] else None

        # Market-state quantities continue to advance for every available bar,
        # even when another subscription is missing and trading must be skipped.
        if spy_bar is not None:
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)

        if aapl_bar is not None:
            previous_aapl_close = self.previous_closes.get("AAPL")
            if previous_aapl_close is None or aapl_bar.Close >= previous_aapl_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)

        all_bars_available = all(available.values())
        if all_bars_available:
            self._evaluate_sells(spy_bar, aapl_bar)
            self._evaluate_buys(spy_bar, aapl_bar)

        if spy_bar is not None:
            self.previous_closes["SPY"] = spy_bar.Close
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value
        if aapl_bar is not None:
            self.previous_closes["AAPL"] = aapl_bar.Close

    def _evaluate_sells(self, spy_bar, aapl_bar):
        previous_spy_close = self.previous_closes.get("SPY")

        # A completed downward close/SMA(50) crossing closes Strategy A's lot.
        if (
            self.strategy_a_shares > 0
            and previous_spy_close is not None
            and self.previous_spy_sma_50 is not None
            and self.spy_sma_50.IsReady
            and previous_spy_close >= self.previous_spy_sma_50
            and spy_bar.Close < self.spy_sma_50.Current.Value
        ):
            self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
