            and self.spy_sma_50.is_ready
            and self.aapl_rsi_14.is_ready
            and self.previous_spy_close is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
            and self.previous_aapl_close is not None
        )

        if all_bars_present and indicators_ready:
            current_sma_200 = self.spy_sma_200.current.value
            current_sma_50 = self.spy_sma_50.current.value

            # Evaluate every sell before either strategy's buy.
            if self.strategy_a_shares > 0:
                crossed_below_sma_50 = (
