class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma_200 = self.SMA(self.spy, 200, Resolution.Daily)
        self.spy_sma_50 = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi_14 = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily,
        )

        self.previous_close = {}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_red_streak = 0

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0
        self.strategy_a_order_id = None
        self.strategy_b_order_id = None

    def OnData(self, data: Slice):
        bars = data.Bars

        if self.aapl in bars:
            close = bars[self.aapl].Close
            old_close = self.previous_close.get(self.aapl)
            if old_close is not None and close < old_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        all_bars_present = all(symbol in bars for symbol in self.symbols.values())
        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
        )
        history_ready = (
            self.previous_close.get(self.spy) is not None
            and self.previous_close.get(self.aapl) is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
        )

        if all_bars_present and indicators_ready and history_ready:
            spy_close = bars[self.spy].Close

            # Sells are evaluated before either strategy's buy.
            if (
                self.strategy_a_quantity > 0
                and self.strategy_a_order_id is None
                and self.previous_close[self.spy]
                >= self.previous_spy_sma_50
                and spy_close < self.spy_sma_50.Current.Value
            ):
                ticket = self.MarketOrder(
                    self.spy, -self.strategy_a_quantity, tag="Strategy A sell"
                )
                self.strategy_a_order_id = ticket.OrderId

            if (
                self.strategy_b_quantity > 0
                and self.strategy_b_order_id is None
                and self.aapl_rsi_14.Current.Value > 60
            ):
                ticket = self.MarketOrder(
                    self.aapl, -self.strategy_b_quantity, tag="Strategy B sell"
                )
                self.strategy_b_order_id = ticket.OrderId

            if (
                self.strategy_a_quantity == 0
                and self.strategy_a_order_id is None
                and self.previous_close[self.spy]
                <= self.previous_spy_sma_200
                and spy_close > self.spy_sma_200.Current.Value
            ):
                quantity = self.CalculateOrderQuantity(self.spy, 0.40)
                if quantity > 0:
                    ticket = self.MarketOrder(
                        self.spy, quantity, tag="Strategy A buy"
                    )
                    self.strategy_a_order_id = ticket.OrderId

            if (
                self.strategy_b_quantity == 0
                and self.strategy_b_order_id is None
                and self.aapl_red_streak >= 3
                and self.Portfolio.Cash >= 20_000
            ):
                quantity = int(20_000 // bars[self.aapl].Close)
                if quantity > 0:
                    ticket = self.MarketOrder(
                        self.aapl, quantity, tag="Strategy B buy"
                    )
                    self.strategy_b_order_id = ticket.OrderId

        if self.spy in bars:
            self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        for symbol, bar in bars.items():
            if symbol in self.symbols.values():
                self.previous_close[symbol] = bar.Close

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                if order_event.OrderId == self.strategy_a_order_id:
                    self.strategy_a_order_id = None
                if order_event.OrderId == self.strategy_b_order_id:
                    self.strategy_b_order_id = None
            return

        if order_event.OrderId == self.strategy_a_order_id:
            self.strategy_a_quantity += order_event.FillQuantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_a_order_id = None

        if order_event.OrderId == self.strategy_b_order_id:
            self.strategy_b_quantity += order_event.FillQuantity
            if order_event.Status == OrderStatus.Filled:
                self.strategy_b_order_id = None

