class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=200)
        self.aapl_closes = deque(maxlen=15)
        self.aapl_initial_gains = []
        self.aapl_initial_losses = []
        self.aapl_average_gain = None
        self.aapl_average_loss = None

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_previous_close = None
        self.spy_previous_sma_200 = None
        self.spy_previous_sma_50 = None
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        sma_200 = None
        sma_50 = None
        spy_close = None
        if "SPY" in bars:
            spy_close = float(bars["SPY"].Close)
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 200:
                sma_200 = sum(self.spy_closes) / 200.0
                sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0

        rsi_14 = None
        aapl_close = None
        if "AAPL" in bars:
            aapl_close = float(bars["AAPL"].Close)
            if self.aapl_closes:
                change = aapl_close - self.aapl_closes[-1]
                gain = max(change, 0.0)
                loss = max(-change, 0.0)
                if self.aapl_average_gain is None:
                    self.aapl_initial_gains.append(gain)
                    self.aapl_initial_losses.append(loss)
                    if len(self.aapl_initial_gains) == 14:
                        self.aapl_average_gain = sum(self.aapl_initial_gains) / 14.0
                        self.aapl_average_loss = sum(self.aapl_initial_losses) / 14.0
                else:
                    self.aapl_average_gain = (self.aapl_average_gain * 13.0 + gain) / 14.0
                    self.aapl_average_loss = (self.aapl_average_loss * 13.0 + loss) / 14.0

                if change < 0:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_closes.append(aapl_close)

        if self.aapl_average_gain is not None:
            if self.aapl_average_loss == 0:
                rsi_14 = 100.0 if self.aapl_average_gain > 0 else 50.0
            else:
                relative_strength = self.aapl_average_gain / self.aapl_average_loss
                rsi_14 = 100.0 - 100.0 / (1.0 + relative_strength)

        if len(bars) != len(self.symbols):
            if spy_close is not None:
                self.spy_previous_close = spy_close
                self.spy_previous_sma_200 = sma_200
                self.spy_previous_sma_50 = sma_50
            return

        # Sells are evaluated before buys.  The SMA(50) exit is the mirror
        # crossover of the SMA(200) entry: SPY's close crosses below SMA(50).
        if self.spy_lot > 0 and self._crosses_below(
            self.spy_previous_close,
            self.spy_previous_sma_50,
            spy_close,
            sma_50,
        ):
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and rsi_14 is not None and rsi_14 > 60.0:
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and self._crosses_above(
            self.spy_previous_close,
            self.spy_previous_sma_200,
            spy_close,
            sma_200,
        ):
            target_value = float(self.Portfolio.TotalPortfolioValue) * 0.40
            quantity = floor(target_value / spy_close)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            cash_required = Decimal("20000")
            if self.Portfolio.Cash >= cash_required:
                quantity = floor(float(cash_required) / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

        self.spy_previous_close = spy_close
        self.spy_previous_sma_200 = sma_200
        self.spy_previous_sma_50 = sma_50

    @staticmethod
    def _crosses_above(previous_x, previous_y, current_x, current_y):
        return (
            previous_x is not None
            and previous_y is not None
            and current_y is not None
            and previous_x <= previous_y
            and current_x > current_y
        )

    @staticmethod
    def _crosses_below(previous_x, previous_y, current_x, current_y):
        return (
            previous_x is not None
            and previous_y is not None
            and current_y is not None
            and previous_x >= previous_y
            and current_x < current_y
        )

