        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_previous_close = None
        self.spy_previous_sma_200 = None
        self.spy_previous_sma_50 = None
        self.aapl_closes = deque(maxlen=4)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_bar = bars.get("SPY")
        if spy_bar is not None:
            spy_close = spy_bar.Close
            self.spy_sma_200.Update(spy_bar.EndTime, spy_close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_close)
        else:
            spy_close = None

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            aapl_close = aapl_bar.Close
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_close)
            self.aapl_closes.append(aapl_close)

        complete_day = len(bars) == len(self.symbols)
        if complete_day:
            self._evaluate_strategy_a(spy_close)
            self._evaluate_strategy_b(aapl_bar.Close)

        if spy_bar is not None:
            self.spy_previous_close = spy_close
            if self.spy_sma_200.IsReady:
                self.spy_previous_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.spy_previous_sma_50 = self.spy_sma_50.Current.Value

    def _evaluate_strategy_a(self, close):
        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.spy_previous_close is not None
            and self.spy_previous_sma_200 is not None
            and self.spy_previous_sma_50 is not None
        )
        if not indicators_ready:
            return

        if self.strategy_a_shares > 0:
            crossed_below_sma_50 = (
                self.spy_previous_close >= self.spy_previous_sma_50
                and close < self.spy_sma_50.Current.Value
            )
            if crossed_below_sma_50:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
            return

        crossed_above_sma_200 = (
            self.spy_previous_close <= self.spy_previous_sma_200
            and close > self.spy_sma_200.Current.Value
        )
        if crossed_above_sma_200:
            shares = floor(0.40 * self.Portfolio.TotalPortfolioValue / close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

    def _evaluate_strategy_b(self, close):
        if not self.aapl_rsi_14.IsReady or len(self.aapl_closes) < 4:
            return

        if self.strategy_b_shares > 0:
            if self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
            return

        red_for_three_days = all(
            self.aapl_closes[index] < self.aapl_closes[index - 1]
            for index in range(1, 4)
        )
        if red_for_three_days and self.Portfolio.Cash >= 20_000:
            shares = floor(20_000 / close)
            if shares > 0:
                self.MarketOrder(self.symbols["AAPL"], shares)
                self.strategy_b_shares = shares

