class IndependentSlotsAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        self._apply_splits(data)

        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        previous_spy_close = self.previous_closes.get("SPY")
        previous_aapl_close = self.previous_closes.get("AAPL")
        previous_sma_200 = self.previous_spy_sma_200
        previous_sma_50 = self.previous_spy_sma_50

        if "SPY" in bars:
            spy_bar = bars["SPY"]
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            if previous_aapl_close is None or aapl_bar.Close >= previous_aapl_close:
                self.aapl_red_streak = 0
            else:
                self.aapl_red_streak += 1
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.Close

        if "SPY" in bars:
            if self.spy_sma_200.IsReady:
                self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            if self.spy_sma_50.IsReady:
                self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        if len(bars) != len(self.symbols):
            return

        self._evaluate_strategy_a(
            bars["SPY"], previous_spy_close, previous_sma_200, previous_sma_50
        )
        self._evaluate_strategy_b(bars["AAPL"])

    def _evaluate_strategy_a(
        self, bar, previous_close, previous_sma_200, previous_sma_50
    ):
        if self.strategy_a_shares > 0:
            if (
                self.spy_sma_50.IsReady
                and previous_close is not None
                and previous_sma_50 is not None
                and previous_close >= previous_sma_50
                and bar.Close < self.spy_sma_50.Current.Value
            ):
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
            return

        if (
            self.spy_sma_200.IsReady
            and previous_close is not None
            and previous_sma_200 is not None
            and previous_close <= previous_sma_200
            and bar.Close > self.spy_sma_200.Current.Value
        ):
            shares = floor(0.40 * self.Portfolio.TotalPortfolioValue / bar.Close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)
                self.strategy_a_shares = shares

    def _evaluate_strategy_b(self, bar):
        if self.strategy_b_shares > 0:
            if self.aapl_rsi_14.IsReady and self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
            return

        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
            shares = floor(20_000 / bar.Close)
            if shares > 0:
                self.MarketOrder(self.symbols["AAPL"], shares)
                self.strategy_b_shares = shares

    def _apply_splits(self, data):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Splits.ContainsKey(spy):
            factor = data.Splits[spy].SplitFactor
            if factor > 0:
                self.strategy_a_shares = int(self.strategy_a_shares / factor)

        if data.Splits.ContainsKey(aapl):
            factor = data.Splits[aapl].SplitFactor
            if factor > 0:
                self.strategy_b_shares = int(self.strategy_b_shares / factor)

from AlgorithmImports import *
from math import floor


class ParallelSlotsAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in tickers
        }

        self.spy_sma_200 = SimpleMovingAverage(200)
        self.spy_sma_50 = SimpleMovingAverage(50)
        self.aapl_rsi_14 = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.previous_closes = {}
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None
        self.aapl_red_streak = 0

        self.strategy_a_quantity = 0
        self.strategy_b_quantity = 0

        self.SetWarmUp(200, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_bar = bars.get("SPY")
        aapl_bar = bars.get("AAPL")

        previous_aapl_close = self.previous_closes.get("AAPL")
        if aapl_bar is not None:
            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_bar.Close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_rsi_14.Update(aapl_bar.EndTime, aapl_bar.Close)

        if spy_bar is not None:
            self.spy_sma_200.Update(spy_bar.EndTime, spy_bar.Close)
            self.spy_sma_50.Update(spy_bar.EndTime, spy_bar.Close)

        all_bars_present = len(bars) == len(self.symbols)
        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
        )

        if all_bars_present and indicators_ready and not self.IsWarmingUp:
            self._evaluate_strategy_a(spy_bar)
            self._evaluate_strategy_b(aapl_bar)

        if spy_bar is not None:
            self.previous_spy_sma_200 = self.spy_sma_200.Current.Value
            self.previous_spy_sma_50 = self.spy_sma_50.Current.Value

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.Close

    def _evaluate_strategy_a(self, bar: TradeBar):
        previous_close = self.previous_closes.get("SPY")
        if (
            previous_close is None
            or self.previous_spy_sma_200 is None
            or self.previous_spy_sma_50 is None
        ):
            return

        close = bar.Close
        if self.strategy_a_quantity > 0:
            crossed_below_sma_50 = (
                previous_close >= self.previous_spy_sma_50
                and close < self.spy_sma_50.Current.Value
            )
            if crossed_below_sma_50:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_quantity)
                self.strategy_a_quantity = 0
            return

        crossed_above_sma_200 = (
            previous_close <= self.previous_spy_sma_200
            and close > self.spy_sma_200.Current.Value
        )
        if crossed_above_sma_200:
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_quantity = quantity

    def _evaluate_strategy_b(self, bar: TradeBar):
        if self.strategy_b_quantity > 0:
            if self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_quantity)
                self.strategy_b_quantity = 0
            return

        allocation = 20_000
        if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= allocation:
            quantity = floor(allocation / bar.Close)
            if quantity > 0:
                self.MarketOrder(self.symbols["AAPL"], quantity)
                self.strategy_b_quantity = quantity

from AlgorithmImports import *

from collections import deque
from math import floor


class ParallelDailyStrategiesAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in self.tickers
        }

        self.spy_closes = deque(maxlen=200)
        self.previous_spy_close = None
        self.previous_spy_sma_200 = None
        self.previous_spy_sma_50 = None

        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.strategy_a_buy_pending = False
        self.strategy_b_buy_pending = False

        self.SetWarmUp(201, Resolution.Daily)

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy_bar = bars.get("SPY")
        spy_sma_200 = None
        spy_sma_50 = None
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
            if len(self.spy_closes) == 200:
                spy_sma_200 = sum(self.spy_closes) / 200.0
                spy_sma_50 = sum(list(self.spy_closes)[-50:]) / 50.0

        aapl_bar = bars.get("AAPL")
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        complete_slice = len(bars) == len(self.tickers)
        indicators_ready = (
            spy_sma_200 is not None
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
            and self.aapl_rsi.IsReady
            and self.previous_aapl_close is not None
        )

        if complete_slice and indicators_ready and not self.IsWarmingUp:
            spy_close = float(spy_bar.Close)

            # Each strategy evaluates its exit before its entry.
            if self.strategy_a_shares > 0:
                crossed_below_sma_50 = (
                    self.previous_spy_close >= self.previous_spy_sma_50
                    and spy_close < spy_sma_50
                )
                if crossed_below_sma_50:
                    self._submit_strategy_a_order(-self.strategy_a_shares)

            if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
                self._submit_strategy_b_order(-self.strategy_b_shares)

            if self.strategy_a_shares == 0 and not self.strategy_a_buy_pending:
                crossed_above_sma_200 = (
                    self.previous_spy_close <= self.previous_spy_sma_200
                    and spy_close > spy_sma_200
                )
                if crossed_above_sma_200:
                    quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
                    if quantity > 0:
                        self.strategy_a_buy_pending = True
                        self._submit_strategy_a_order(quantity)

            if self.strategy_b_shares == 0 and not self.strategy_b_buy_pending:
                if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20_000:
                    quantity = floor(20_000 / float(aapl_bar.Close))
                    if quantity > 0:
                        self.strategy_b_buy_pending = True
                        self._submit_strategy_b_order(quantity)

        if spy_bar is not None:
            self.previous_spy_close = float(spy_bar.Close)
            if spy_sma_200 is not None:
                self.previous_spy_sma_200 = spy_sma_200
                self.previous_spy_sma_50 = spy_sma_50
        if aapl_bar is not None:
            self.previous_aapl_close = float(aapl_bar.Close)

    def _submit_strategy_a_order(self, quantity):
        self.MarketOrder(self.symbols["SPY"], quantity, tag="Strategy A")

    def _submit_strategy_b_order(self, quantity):
        self.MarketOrder(self.symbols["AAPL"], quantity, tag="Strategy B")

    def OnOrderEvent(self, order_event: OrderEvent):
        is_strategy_a = order_event.Symbol == self.symbols["SPY"]
        is_strategy_b = order_event.Symbol == self.symbols["AAPL"]
        if not is_strategy_a and not is_strategy_b:
            return

        if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
            fill_quantity = int(order_event.FillQuantity)
            if is_strategy_a:
                self.strategy_a_shares += fill_quantity
            else:
                self.strategy_b_shares += fill_quantity

        if order_event.Status in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            if is_strategy_a:
                self.strategy_a_buy_pending = False
            else:
                self.strategy_b_buy_pending = False
